-- El Libro Infinito · contenido inicial (párrafo de Chusi + 17 de arranque + resumen)
-- Pega este archivo en Supabase → SQL Editor → Run, después de 0001_init.sql.

insert into public.paragraphs (n, username, body, signed, gold, word_count, created_at) values
  (1, 'Jesús Chusi Martín', 'Hace tiempo quiero contar esta historia, mas nunca encontré el momento apropiado para hacerlo. Yo tenía un tío llamado Paco que un día, sin mediar palabra, cargó una mochila y marchó a Barcelona. En aquella época no existían los móviles y nunca pudimos localizarlo.
Cientos de preguntas quedaron en el aire... ¿Por qué se fue?, ¿Por qué no avisó a nadie de la familia, ni siquiera a su propia esposa?, ¿Qué había en esa mochila que llevó como único equipaje?', true, false, 80, now() - interval '697 minutes'),
  (2, 'mari_luz_83', 'Yo solo digo que nadie se va con una sola mochila si piensa volver.', false, false, 14, now() - interval '656 minutes'),
  (3, 'Rosa_Bermúdez', 'La tía Rosario tardó tres días en abrir el congelador. Cuando por fin lo hizo, entre una bolsa de habas y un táper de croquetas, encontró una nota doblada en cuatro, escrita con el lápiz de carpintero que Paco llevaba siempre detrás de la oreja: «No me esperes para cenar. Ni mañana tampoco». Nadie entendió por qué la había dejado precisamente ahí. Rosario decía que era el único sitio de la casa que ella abría todos los días.', false, false, 78, now() - interval '615 minutes'),
  (4, 'banana_loca', 'Las croquetas, por cierto, también desaparecieron.', true, false, 6, now() - interval '574 minutes'),
  (5, 'el_profe_de_historia', 'Hay un detalle que se suele olvidar: la nota estaba escrita por detrás de un mapa. Un mapa del Mediterráneo con una cruz pintada a mano en mitad del mar.', false, false, 30, now() - interval '533 minutes'),
  (6, 'Carmen_LR', 'Lo de la cruz tiene una explicación menos romántica. Mi madre, que era vecina de Rosario, vio aquel papel años después: no era un mapa, sino un mantel de papel de «La Taberna del Pirata Cojo», un restaurante de carretera donde a los niños les regalaban un parche en el ojo. Lo raro es que la cruz no venía impresa. Alguien la había dibujado a bolígrafo, apretando mucho, sobre un punto donde no había nada más que agua.', false, false, 78, now() - interval '492 minutes'),
  (7, 'xX_DarkLord_Xx', 'La Taberna del Pirata Cojo era en realidad una base secreta.', false, false, 11, now() - interval '451 minutes'),
  (8, 'Paqui_Granada', 'Base secreta no sé, pero las sardinas las ponían buenísimas. Mi padre paraba allí cada vez que bajaba a Almería con el camión.', false, false, 23, now() - interval '410 minutes'),
  (9, 'mochilero_76', '¿Y nadie se pregunta qué hacía Paco en un restaurante de piratas, si decían que nunca salía del pueblo?', false, false, 19, now() - interval '369 minutes'),
  (10, 'Jordi_Tarragona', 'Escribo desde Tarragona y esto me ha puesto los pelos de punta. Cuando yo era pequeño, a finales de los ochenta, mi abuelo nos contaba en la playa de l''Arrabassada la historia de un andaluz errante que dormía en la arena y que, a cambio de un plato de comida, sacaba de su mochila artilugios que nadie había visto nunca. Una brújula que no señalaba el norte. Un reloj sin agujas. Mi abuelo juraba que aquel hombre se llamaba Paco.', true, true, 80, now() - interval '328 minutes'),
  (11, 'abuela_conchi', 'Una brújula que no señala el norte. Como el tío Paco, vamos.', false, false, 12, now() - interval '287 minutes'),
  (12, 'Lucía_desde_Lima', 'Saludos desde Perú, me lo he leído todo de un tirón. Si la brújula no señalaba el norte, ¿qué señalaba?', false, false, 20, now() - interval '246 minutes'),
  (13, 'lectora_seria', 'Voy a intentar poner un poco de orden. Tenemos tres pistas: la nota del congelador, la cruz dibujada a bolígrafo en el mantel del Pirata Cojo y la brújula que, según el abuelo de Jordi, no señalaba el norte. Si Paco marcó un punto en mitad del mar y luego viajaba con una brújula que apuntaba a otra parte, quizá no estaba perdido. Quizá iba a un sitio muy concreto, y en la mochila llevaba justo lo que necesitaba para llegar.', false, false, 81, now() - interval '205 minutes'),
  (14, 'TheRealPepe', 'O un bocadillo de chorizo. Nunca lo sabremos.', false, false, 8, now() - interval '164 minutes'),
  (15, 'Mercedes_RM', 'Soy prima segunda de la familia y hay algo que en casa nunca se contaba. La noche antes de irse, Paco estuvo en el taller hasta las tantas. Mi madre lo vio por la ventana metiendo cosas en la mochila con muchísimo cuidado, envueltas en papel de periódico, como si fueran de cristal. Cuando le preguntó qué hacía, él solo contestó: «Devolver lo que no es mío».', true, false, 67, now() - interval '123 minutes'),
  (16, 'guionista_frustrado', 'Giro de guion: lo que no era suyo era la mochila. Y su verdadero dueño lleva casi cuarenta años buscándola.', false, false, 20, now() - interval '82 minutes'),
  (17, 'Kenji_Tokyo', 'I don''t speak Spanish, but I used a translator and now I NEED to know what is in the backpack.', false, false, 20, now() - interval '41 minutes'),
  (18, 'nachete', 'Y mientras todos discutíamos de brújulas y manteles, nadie se fijó en lo más evidente: la mochila de Paco era verde militar y tenía dos iniciales bordadas en la solapa, J. M. Ninguna de las dos letras era suya.', true, false, 39, now() - interval '0 minutes');

insert into public.book_summary (id, sections, after_n) values (1, '[{"title": "Cómo empezó", "text": "Chusi abrió el libro con un misterio de familia: su tío Paco cargó una mochila y se marchó a Barcelona sin avisar a nadie, ni siquiera a su mujer. Nunca volvieron a saber de él."}, {"title": "Las pistas", "text": "Una nota en el congelador de la tía Rosario: «No me esperes para cenar. Ni mañana tampoco». Escrita detrás de un mantel de papel de La Taberna del Pirata Cojo, con una cruz a bolígrafo en mitad del mar. Desde Tarragona, Jordi recuerda a un andaluz errante con una brújula que no señalaba el norte y un reloj sin agujas."}, {"title": "El gran enigma", "text": "Nadie sabe qué había en la mochila. La noche antes de irse, Paco guardó cosas envueltas en periódico y dijo que iba a «devolver lo que no es mío». Ahora sabemos que la mochila tenía bordadas las iniciales J. M., y que ninguna de las dos letras era suya."}, {"title": "Las teorías", "text": "Las croquetas de Rosario (banana_loca), un bocadillo de chorizo (TheRealPepe) o que la mochila tenía otro dueño que aún la busca (guionista_frustrado). xX_DarkLord_Xx sigue convencido de que el restaurante era una base secreta."}]'::jsonb, 18);
